#!/usr/bin/env bash
# Harbor's whole cycle on a project generated by Keelokit, with Keelokit's real verify and hooks.
#
#   scripts/test-with-keelokit.sh [TAG]      default v0.11.0
#
# KEELOKIT_SRC: the template (default gh:leosimini/keelokit; a local clone works). KEEP=1 keeps the
# work folder. Needs git, uv, pnpm and Node 22; no Docker: the project is web-only, so no step needs a
# database. What it proves, each with an assertion:
#   - a vessel verified the way build-story does (`pnpm verify --since origin/main`) is sealed from
#     Keelokit's history, without a second run, and the seal carries a level;
#   - another clone (another machine) accepts that kind of seal through [verify] shared_seals;
#   - assemble, the ok, the convoy's one verify and the sail end with main at the convoy's head,
#     pushed through Keelokit's own pre-push hook; the verify that hook runs when assemble pushes
#     convoy/<n> is the convoy's verify, so `convoy verify` runs nothing.
# In a container whose Playwright browsers don't match the template's, point PLAYWRIGHT_BROWSERS_PATH
# at a folder with the right version name linked to the browser you have.
set -euo pipefail

tag=${1:-v0.11.0}
src=${KEELOKIT_SRC:-gh:leosimini/keelokit}
harbor=$(cd "$(dirname "$0")/.." && pwd)/bin/harbor.py
work=$(mktemp -d)
[ "${KEEP:-}" = 1 ] && echo "work folder: $work" || trap 'rm -rf "$work"' EXIT
export GIT_AUTHOR_NAME=harbor-test GIT_AUTHOR_EMAIL=harbor-test@example.com
export GIT_COMMITTER_NAME=harbor-test GIT_COMMITTER_EMAIL=harbor-test@example.com
export KEELOKIT_ALLOW_MISSING="${KEELOKIT_ALLOW_MISSING:-gitleaks semgrep}"
step() { printf '\n\033[1m▶ %s\033[0m\n' "$*"; }
fail() { printf '\n\033[31m✖ %s\033[0m\n' "$*" >&2; exit 1; }
H() { local s=$1; shift; python3 "$harbor" --session "$s" "$@"; }
seal_of() { git -C "$1" show "origin/harbor/log:harbor/seals/$2.toml"; }

step "Generate a web-only project from Keelokit $tag"
seed=$work/seed
mkdir -p "$seed/docs/context"
git -C "$seed" init -q -b main
for f in product domain constraints environments; do printf '# %s\n\nStub.\n' "$f" >"$seed/docs/context/$f.md"; done
printf '# Gaps\n\n| Id | File | Missing | Owner | Question | Blocking |\n|---|---|---|---|---|---|\n' >"$seed/docs/context/gaps.md"
uvx copier==9.18.2 copy --quiet --vcs-ref "$tag" --defaults --data project_name=Demo --data 'apps=["web"]' \
  --data postgis=false "$src" "$seed"
cat >>"$seed/.keelokit/state.toml" <<'TOML'

[landing]
policy = "convoy"

[verify]
shared_seals = "origin/harbor/log:harbor/seals/{head}.toml"

[harbor]
ci_check = ""
TOML
printf '.keelokit/local.toml\n' >>"$seed/.gitignore"
# Committed before `pnpm install`, whose `prepare` turns the hooks on, as Keelokit's test-template.sh does:
# the template's ci.yml carries a `continue-on-error` its own pre-commit guard (QA-4) would stop.
git -C "$seed" add -A
git -C "$seed" commit -qm "Demo, generated by Keelokit $tag, under Harbor"
(cd "$seed" && pnpm install --silent && { pnpm -r --if-present --workspace-concurrency=1 e2e:install >/dev/null 2>&1 || true; })
git -C "$seed" add -A
git -C "$seed" diff --cached --quiet || git -C "$seed" commit -qm "pnpm install"
git init -q --bare -b main "$work/remote.git"
git -C "$seed" remote add origin "$work/remote.git"
git -C "$seed" push -q origin main

clone() { # clone NAME HOST: one machine
  local dir=$work/$1
  git clone -q "$work/remote.git" "$dir"
  printf '[harbor]\naccount = "leo"\nhost = "%s"\n' "$2" >"$dir/.keelokit/local.toml"
  git -C "$dir" config core.hooksPath .githooks
  (cd "$dir" && pnpm install --silent --frozen-lockfile)
  echo "$dir"
}
a=$(clone a mbp | tail -1)
b=$(clone b linux | tail -1)

step "The logbook, the account, a skipper who holds the watch"
cd "$a"
H s1 init
H s1 account set leo --max-sessions 4
H s1 worker register --role skipper --model sonnet
H s1 harbormaster takeover

vessel() { # vessel BRANCH FILE CONTENT STORY: a story built and verified the way build-story does it
  git -C "$a" checkout -q -B "$1" origin/main
  mkdir -p "$(dirname "$a/$2")"
  printf '%s' "$3" >"$a/$2"
  (cd "$a" && pnpm exec prettier --write "$2" >/dev/null)
  git -C "$a" add -A
  git -C "$a" commit -qm "feat: $1" -m "Story: $4"
  (cd "$a" && pnpm verify --since origin/main) >"$work/verify-$4.log" 2>&1 || { tail -40 "$work/verify-$4.log"; fail "verify of $4 is red"; }
  git -C "$a" push -q -u origin "$1"
  out=$(H s1 seal)
  echo "$out"
  grep -q "already passed Keelokit's verify" <<<"$out" || fail "the seal of $4 ran the verify again instead of reusing it"
  grep -q "pre-push accepts it" <<<"$out" || fail "the seal of $4 has no level"
}

step "Two vessels: a code change and a docs change"
vessel claude/demo-1 apps/web/src/harbor-demo.ts 'export const harborDemo = 1;
' DEMO-1
vessel claude/demo-2 docs/harbor-demo.md '# Harbor demo

A docs-only vessel.
' DEMO-2
v1=$(git -C "$a" rev-parse claude/demo-1)

step "Another machine accepts the vessel's seal without running the verify"
git -C "$b" fetch -q origin claude/demo-1 harbor/log
git -C "$b" checkout -q -B claude/demo-1 origin/claude/demo-1
out=$(cd "$b" && timeout 300 pnpm verify --use-seal 2>&1) || { echo "$out" | tail -20; fail "the shared seal was not accepted on the other clone"; }
echo "$out" | grep "shared seal" || { echo "$out" | tail -20; fail "the other clone ran the verify instead of using the shared seal"; }

step "The convoy: new, add, assemble, ok, one verify, sail"
H s1 convoy new --title "Harbor on Keelokit $tag" --expect DEMO-1 DEMO-2
H s1 convoy add 1 claude/demo-1 --tier light
H s1 convoy add 1 claude/demo-2 --tier trivial
out=$(H s1 convoy assemble 1)
echo "$out"
grep -q "recorded as the convoy's seal" <<<"$out" || fail "the pre-push verify of convoy/1 was not recorded as its seal"
H s1 convoy sail 1 --ok --level changed --reason "apps/web and docs only"
H s1 convoy verify 1 >"$work/convoy-verify.log" 2>&1 || { tail -60 "$work/convoy-verify.log"; fail "the convoy verify is red"; }
tail -3 "$work/convoy-verify.log"
grep -q "nothing to run" "$work/convoy-verify.log" || fail "the convoy verify ran again what assemble's push had verified"
H s1 convoy sail 1 2>&1 | tee "$work/sail.log"
head=$(git -C "$a" rev-parse convoy/1)
[ "$(git -C "$work/remote.git" rev-parse main)" = "$head" ] || fail "main is not at the convoy's head"
git -C "$work/remote.git" merge-base --is-ancestor "$v1" main || fail "vessel DEMO-1 is not on main"
seal_of "$a" "$head" | grep -q '^level = "changed"' || fail "the convoy's seal has no level"

step "The round and the logbook"
H s1 harbormaster control
git -C "$a" show origin/harbor/log:LOGBOOK.md | sed -n '1,40p'
printf '\n\033[32m✔ Harbor on Keelokit %s: vessels sealed once, seal shared across clones, one convoy on main at %s\033[0m\n' \
  "$tag" "${head:0:9}"
